update RB_ACCT_BALANCE
set
    INTERNAL_KEY = #{row.internalKey,jdbcType=INTEGER},            TOTAL_AMOUNT = #{row.totalAmount,jdbcType=DECIMAL},            TOTAL_AMOUNT_PREV = #{row.totalAmountPrev,jdbcType=DECIMAL},            TOTAL_AMOUNT_LAST_PREV = #{row.totalAmountLastPrev,jdbcType=DECIMAL},            PLD_AMOUNT = #{row.pldAmount,jdbcType=DECIMAL},            FINREG_AMOUNT = #{row.finregAmount,jdbcType=DECIMAL},            DOS_AMOUNT = #{row.dosAmount,jdbcType=DECIMAL},            OD_AMOUNT = #{row.odAmount,jdbcType=DECIMAL},            ODD_AMOUNT = #{row.oddAmount,jdbcType=DECIMAL},            LAST_BAL_UPD_DATE = #{row.lastBalUpdDate,jdbcType=TIMESTAMP},            LAST_CHANGE_DATE = #{row.lastChangeDate,jdbcType=TIMESTAMP},            LAST_CHANGE_USER_ID = #{row.lastChangeUserId,jdbcType=VARCHAR},            CLIENT_NO = #{row.clientNo,jdbcType=VARCHAR},            DAC_VALUE = #{row.dacValue,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{row.tranTimestamp,jdbcType=VARCHAR},            COMPANY = #{row.company,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{row.createTimestamp,jdbcType=VARCHAR}

update RB_ACCT_BALANCE
set
    TOTAL_AMOUNT = #{totalAmount,jdbcType=DECIMAL},            TOTAL_AMOUNT_PREV = #{totalAmountPrev,jdbcType=DECIMAL},            TOTAL_AMOUNT_LAST_PREV = #{totalAmountLastPrev,jdbcType=DECIMAL},            PLD_AMOUNT = #{pldAmount,jdbcType=DECIMAL},            FINREG_AMOUNT = #{finregAmount,jdbcType=DECIMAL},            DOS_AMOUNT = #{dosAmount,jdbcType=DECIMAL},            OD_AMOUNT = #{odAmount,jdbcType=DECIMAL},            ODD_AMOUNT = #{oddAmount,jdbcType=DECIMAL},            LAST_BAL_UPD_DATE = #{lastBalUpdDate,jdbcType=TIMESTAMP},            LAST_CHANGE_DATE = #{lastChangeDate,jdbcType=TIMESTAMP},            LAST_CHANGE_USER_ID = #{lastChangeUserId,jdbcType=VARCHAR},            DAC_VALUE = #{dacValue,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{tranTimestamp,jdbcType=VARCHAR},            COMPANY = #{company,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{createTimestamp,jdbcType=VARCHAR}        where INTERNAL_KEY = #{internalKey,jdbcType=INTEGER}
  and CLIENT_NO = #{clientNo,jdbcType=VARCHAR}
